"harrow.greet.blunt": {
"d": 4.78,
"kind": "greet",
"speaker": "harrow",
"src": "voices/harrow/harrow.greet.blunt.mp3",
"t": "You shout like that again and I'll put you out through the thorn myself.",
"voiceOf": "harrow"
},
"harrow.greet.normal": {
"d": 2.98,
"kind": "greet",
"speaker": "harrow",
"src": "voices/harrow/harrow.greet.normal.mp3",
"t": "Gate's shut after dusk. Keep it low.",
"voiceOf": "harrow"
},
"harrow.greet.polite": {
"d": 5.18,
"kind": "greet",
"speaker": "harrow",
"src": "voices/harrow/harrow.greet.polite.mp3",
"t": "Keep your voice down, friend, and welcome to what's left of Oakhaven.",
"voiceOf": "harrow"
},
"hetty.greet.blunt": {
"d": 4.08,
"kind": "greet",
"speaker": "hetty",
"src": "voices/hetty/hetty.greet.blunt.mp3",
"t": "I've put bigger men than you out of here for raising their voice. Sit.",
"voiceOf": "hetty"
},
"hetty.greet.normal": {
"d": 4.56,
"kind": "greet",
"speaker": "hetty",
"src": "voices/hetty/hetty.greet.normal.mp3",
"t": "Beer's a copper. Rooms are a sovereign. Singing is free and it will get you killed.",
"voiceOf": "hetty"
},
"hetty.greet.polite": {
"d": 5.4,
"kind": "greet",
"speaker": "hetty",
"src": "voices/hetty/hetty.greet.polite.mp3",
"t": "Sit anywhere that isn't broken. Small beer or smaller. We do not sing in here, not since Davin.",
"voiceOf": "hetty"
},
"hob.greet.blunt": {
"d": 3.22,
"kind": "greet",
"speaker": "hob",
"src": "voices/hob/hob.greet.blunt.mp3",
"t": "I have buried two apprentices this year. Try me.",
"voiceOf": "hob"
},
"hob.greet.normal": {
"d": 4.58,
"kind": "greet",
"speaker": "hob",
"src": "voices/hob/hob.greet.normal.mp3",
"t": "Tannery's shut. Nobody wants leather off a town that is turning to wood.",
"voiceOf": "hob"
},
"hob.greet.polite": {
"d": 3.96,
"kind": "greet",
"speaker": "hob",
"src": "voices/hob/hob.greet.polite.mp3",
"t": "Evening. Mind the vats; the lime does not care who you are.",
"voiceOf": "hob"
},
"ignatius.greet.blunt": {
"d": 7.34,
"kind": "greet",
"speaker": "ignatius",
"src": "voices/ignatius/ignatius.greet.blunt.mp3",
"t": "I have burned men for less than that tone. I am tired, and the Note is long, and you will not try me again.",
"voiceOf": "ignatius"
},
"ignatius.greet.normal": {
"d": 7.92,
"kind": "greet",
"speaker": "ignatius",
"src": "voices/ignatius/ignatius.greet.normal.mp3",
"t": "This chapel had bells once. The Synod took them for bore-teeth, and it was right to. A bell is a voice with nobody inside it.",
"voiceOf": "ignatius"
},
"ignatius.greet.polite": {
"d": 4.78,
"kind": "greet",
"speaker": "ignatius",
"src": "voices/ignatius/ignatius.greet.polite.mp3",
"t": "The Note is held. You may speak under it. Quietly, and in tune.",
"voiceOf": "ignatius"
},
